    es: "La extracción de IA puede cometer errores en recetas escritas a mano o en envases ambiguos. Siempre verifique el nombre y la dosis de cada medicamento extraído con la prescripción original de su médico antes de tomar medidas.",
    fr: "L’extraction par l’IA peut commettre des erreurs sur des prescriptions manuscrites ou des emballages ambigus. Vérifiez toujours le nom et la posologie de chaque médicament extrait par rapport à la prescription originale de votre médecin avant d'agir.",
    de: "Die KI-Extraktion kann zu Fehlern bei handgeschriebenen Rezepten oder mehrdeutigen Verpackungen führen. Überprüfen Sie immer den Namen und die Dosierung jedes extrahierten Arzneimittels anhand Ihrer ursprünglichen ärztlichen Verschreibung, bevor Sie Maßnahmen ergreifen.",
