    de: "Vermeiden Sie chronisch starken Alkoholkonsum, da das Risiko einer schweren Lebertoxizität besteht.",
    zh: "避免长期大量饮酒，因为存在严重的肝毒性风险。",
    ko: "심각한 간 독성 위험이 있으므로 만성적인 과도한 음주를 피하십시오.",
