    de: "Vermeiden Sie große Mengen Grapefruitsaft (mehr als 1,2 Liter täglich).",
    zh: "避免大量饮用葡萄柚汁（每天超过 1.2 升）。",
    ko: "다량의 자몽 주스(매일 1.2리터 이상)를 피하세요.",
