    es: "Busque y agregue 2 o más medicamentos para verificar instantáneamente interacciones peligrosas, riesgos de sangrado, advertencias de alimentos/alcohol y espaciado de dosis.",
    fr: "Recherchez et ajoutez 2 médicaments ou plus pour vérifier instantanément les interactions médicamenteuses dangereuses, les risques de saignement, les avertissements nourriture/alcool et l'espacement des doses.",
    de: "Suchen und fügen Sie 2 oder mehr Medikamente hinzu, um sofort auf gefährliche Wechselwirkungen, Blutungsrisiken, Nahrungsmittel-/Alkohol-Warnungen und Dosisabstände zu prüfen.",
    zh: "搜索并添加 2 种或更多药物，立即可检查危险的药物相互作用、出血风险、食物/酒精警告和用药间隔指导。",
    ko: "2개 이상의 약물을 검색하여 추가하면 위험한 약물 상호작용, 출혈 위험, 음식/알코올 경고 및 복용 간격 지침을 즉시 확인할 수 있습니다.",
