export function translateUi(text: string, language: Language): string {
  if (language === "en" || !text) {
    return text;
  }

  const targetLang = language as TargetLanguage;

  // 1. Exact match in dictionary
  if (uiTranslations[text]?.[targetLang]) {
    return uiTranslations[text][targetLang]!;
  }

  // 2. Whitespace trimmed match + preservation of outer spaces
  const trimmed = text.trim();
  if (trimmed !== text && uiTranslations[trimmed]?.[targetLang]) {
    const translation = uiTranslations[trimmed][targetLang]!;
    const leadingSpaces = text.match(/^\s*/)?.[0] || "";
    const trailingSpaces = text.match(/\s*$/)?.[0] || "";
    return `${leadingSpaces}${translation}${trailingSpaces}`;
  }

  // 3. Trailing punctuation stripping (e.g., "Age:", "Symptoms:", "Loading...", "Ready!")
  const punctMatch = trimmed.match(/^(.+?)([:!?.…]+)$/);
  if (punctMatch) {
    const core = punctMatch[1].trim();
    const punct = punctMatch[2];
    const coreTrans = uiTranslations[core]?.[targetLang] || clinicalGlossary[core]?.[targetLang];
    if (coreTrans) {
      const leadingSpaces = text.match(/^\s*/)?.[0] || "";
      const trailingSpaces = text.match(/\s*$/)?.[0] || "";
      return `${leadingSpaces}${coreTrans}${punct}${trailingSpaces}`;
    }
  }

  // 4. Clinical Glossary match
  if (clinicalGlossary[trimmed]?.[targetLang]) {
    const translation = clinicalGlossary[trimmed][targetLang]!;
    const leadingSpaces = text.match(/^\s*/)?.[0] || "";
    const trailingSpaces = text.match(/\s*$/)?.[0] || "";
    return `${leadingSpaces}${translation}${trailingSpaces}`;
  }

  // 5. Leading emoji/symbol extraction (e.g., "👋 Hi there!", "❤️ Heart Rate")
  const emojiMatch = trimmed.match(/^([\uD800-\uDBFF][\uDC00-\uDFFF]|\p{Emoji}|\p{Symbol}|\s|[-•*])+\s*(.+)$/u);
  if (emojiMatch) {
    const symbolPrefix = trimmed.slice(0, trimmed.length - emojiMatch[2].length);
    const textPart = emojiMatch[2];
    const trans = uiTranslations[textPart]?.[targetLang] || clinicalGlossary[textPart]?.[targetLang];
    if (trans) {
      return `${symbolPrefix}${trans}`;
    }
  }

  // 6. Case-insensitive lookup fallback
  const lower = trimmed.toLowerCase();
  for (const [key, val] of Object.entries(uiTranslations)) {
    if (key.toLowerCase() === lower && val?.[targetLang]) {
      return val[targetLang]!;
    }
  }

  return text;
}
